const fs=require('node:fs'),crypto=require('node:crypto');
const root='holiday-lab/reports/guide-internship-research-20261023';
const sha=f=>crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex');
const x=JSON.parse(fs.readFileSync(root+'/sources.json','utf8'));
const v=JSON.parse(fs.readFileSync(root+'/verification.json','utf8'));
const ctx=JSON.parse(fs.readFileSync(root+'/local-context.json','utf8'));
const report=fs.readFileSync(root+'/REPORT.md','utf8');
const errors=[];let raw=0,png=0,steps=0,faq=0;
for(const f of v.file_manifest)if(!fs.existsSync(f.file)||sha(f.file)!==f.sha256)errors.push('manifest '+f.file);
for(const s of x.sources){
 const r=s.raw||s.receipt;
 if(r?.file&&r.sha256){raw++;if(sha(r.file)!==r.sha256)errors.push('raw '+s.sid);}
 const p=(s.raw||s.receipt)?.file;
 if(p?.endsWith('.pdf'))for(const page of s.visual_pages||[]){png++;if(!fs.existsSync(p.slice(0,-4)+'-page-'+page+'.png'))errors.push('PNG '+s.sid+' '+page);}
}
for(const i of ctx.inputs)if(sha(i.file)!==i.sha256)errors.push('input '+i.file);
for(const title of ['校外實習','海外實習','海外見學']){
 const a=report.slice(report.indexOf('### '+title+'\n')+1);
 const j=a.indexOf('\n### ');const p=j<0?a:a.slice(0,j);
 const z=[...p.matchAll(/#### [1-4]\. [^\n]+\n\n([^\n]+)/g)];
 const q=[...p.matchAll(/^- \*\*Q[1-3]：/gm)];steps+=z.length;faq+=q.length;
 if(z.length!==4||q.length!==3||z.some(m=>{const c=(m[1].match(/[。！？]/g)||[]).length;return c<2||c>3}))errors.push('student structure '+title);
}
const defs=[...report.matchAll(/^\[(S\d+)\]: (.+)$/gm)];
if(defs.length!==23||defs.some(m=>x.sources.find(s=>s.sid===m[1])?.url!==m[2]))errors.push('reference definitions');
console.log(JSON.stringify({all:errors.length===0,manifest_files:v.file_manifest.length,sources:x.sources.length,raw_receipts:raw,pdf_visual_pages:png,steps,faq,errors},null,2));
if(errors.length)process.exitCode=1;
